<script setup lang="ts">
import type { ConnectorAction, ConnectorConnection, ConnectorDefinition, ConnectorInstallation } from '../types';
defineProps<{open:boolean;connector?:ConnectorDefinition;installation?:ConnectorInstallation;connections:ConnectorConnection[]}>();
const emit=defineEmits<{(e:'update:open',v:boolean):void;(e:'test',a:ConnectorAction):void;(e:'connection',c?:ConnectorConnection):void;(e:'toggle'):void}>();
</script>
<template><div v-if="open" class="mask" @click.self="emit('update:open',false)"><aside><header><div><span class="icon">{{connector?.icon||'🔌'}}</span><span><b>{{connector?.name}}</b><small>{{connector?.key.provider}} / {{connector?.key.connectorId}}</small></span></div><button @click="emit('update:open',false)">×</button></header><main><p>{{connector?.description}}</p><div class="meta"><span>版本 {{connector?.version}}</span><span>{{connector?.trustLevel}}</span><span>{{connector?.license||'License 未声明'}}</span></div><section><div class="title"><h3>连接配置</h3><button class="primary" @click="emit('connection')">+ 新建连接</button></div><div v-if="connections.length===0" class="empty">尚未配置连接</div><button v-for="c in connections" :key="c.id" class="row" @click="emit('connection',c)"><span><b>{{c.name}}</b><small>{{c.status}}</small></span><span>{{c.credentialsConfigured?'凭证已配置':'未配置凭证'}} ›</span></button></section><section><h3>Actions</h3><button v-for="a in connector?.actions||[]" :key="a.id" class="row" @click="emit('test',a)"><span><b>{{a.name}}</b><small>{{a.description}}</small></span><span :class="['risk',a.riskLevel?.toLowerCase()]">{{a.riskLevel||'WRITE'}} · 测试 ›</span></button></section></main><footer><button @click="emit('toggle')">{{installation?.enabled?'禁用 Connector':'启用 Connector'}}</button></footer></aside></div></template>
